#!/usr/bin/env node
/**
 * Help content generator. Deterministic: same inputs, same bytes out.
 *
 * Inputs
 *   src/help/topics/*.md      authored topics (front matter: title, order, parent, keywords, aliases)
 *   src/help/imported/*.md    copies of the engine docs (scripts/sync-help.sh), split by `##` headings
 *   src/help/build/extra-aliases.json   hand-curated alias -> topic id
 * Outputs (committed, regenerated by predev/prebuild/pretest)
 *   src/help/generated/topics.json         topics + alias map
 *   src/help/generated/search-index.json   flat search entries
 */
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkTopics } from './guards.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const topicsDir = join(root, 'topics');
const importedDir = join(root, 'imported');
const outDir = join(root, 'generated');

/** Which imported file becomes which family of topics. */
const IMPORTS = [
  {
    file: 'TF-LANGUAGE.md',
    parent: 'scripting',
    prefix: 'scripting/',
    family: 'tf',
    overview: 'Reference overview',
  },
  {
    file: 'TF-COMPAT.md',
    parent: 'compat',
    prefix: 'compat/',
    family: 'compat',
    overview: 'Reading the matrix',
  },
  { file: 'LUA-API.md', parent: 'lua', prefix: 'lua/', family: 'lua', overview: 'Overview of the API' },
];

const fail = (msg) => {
  console.error(`build-help: ${msg}`);
  process.exit(1);
};

// ---------------------------------------------------------------- helpers

/** Alias/lookup normalisation. Keep identical to normalizeKey() in src/help/lookup.ts. */
export const normalizeKey = (s) =>
  s.toLowerCase().trim().replace(/^\/+/, '').replace(/\(\)$/, '').replace(/\s+/g, ' ');

const plain = (s) =>
  s
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[`*_]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const slugify = (s) =>
  plain(s)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'section';

function parseFrontMatter(text, where) {
  const m = /^---\n([\s\S]*?)\n---\n?/.exec(text);
  if (!m) fail(`${where}: missing front matter`);
  const meta = {};
  for (const line of m[1].split('\n')) {
    if (!line.trim()) continue;
    const i = line.indexOf(':');
    if (i < 0) fail(`${where}: bad front matter line "${line}"`);
    meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return { meta, body: text.slice(m[0].length) };
}

const list = (v) =>
  (v ?? '')
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean);

const FENCE = /^\s*(```|~~~)/;
const HEADING = /^(#{1,6})\s+(.*?)\s*#*\s*$/;

/** Scan headings outside code fences; returns [{line, level, raw}]. */
function scanHeadings(lines) {
  const out = [];
  let fence = null;
  lines.forEach((ln, i) => {
    const f = FENCE.exec(ln);
    if (f) {
      if (!fence) fence = f[1];
      else if (f[1] === fence) fence = null;
      return;
    }
    if (fence) return;
    const h = HEADING.exec(ln);
    if (h) out.push({ line: i, level: h[1].length, raw: h[2] });
  });
  return out;
}

/** Unique anchor ids for a page, in document order. */
function anchorize(heads) {
  const seen = new Map();
  return heads.map((h) => {
    const base = slugify(h.raw);
    const n = (seen.get(base) ?? 0) + 1;
    seen.set(base, n);
    return { id: n === 1 ? base : `${base}-${n}`, text: plain(h.raw), level: h.level, line: h.line };
  });
}

/** Search entries and the heading list for one topic body. */
function analyse(topic) {
  const lines = topic.body.split('\n');
  const heads = anchorize(scanHeadings(lines));
  topic.headings = heads.map(({ id, text, level }) => ({ id, text, level }));

  const entries = [];
  const add = (anchor, kind, text) => {
    const t = text.replace(/\s+/g, ' ').trim();
    if (t) entries.push([topic.id, anchor, kind, t]);
  };
  add('', 't', topic.title);
  for (const h of heads) add(h.id, 'h', h.text);
  if (topic.keywords.length) add('', 'k', topic.keywords.join(' '));
  for (const a of topic.aliases) add('', 'k', a);

  let anchor = '';
  let fence = null;
  let fenceBuf = [];
  let para = [];
  const flush = () => {
    if (para.length) add(anchor, 'b', plain(para.join(' ')));
    para = [];
  };
  const headAt = new Map(heads.map((h) => [h.line, h]));
  lines.forEach((ln, i) => {
    const f = FENCE.exec(ln);
    if (f) {
      if (!fence) {
        flush();
        fence = f[1];
        fenceBuf = [];
      } else if (f[1] === fence) {
        add(anchor, 'b', fenceBuf.join(' '));
        fence = null;
      }
      return;
    }
    if (fence) {
      fenceBuf.push(ln.trim());
      return;
    }
    const h = headAt.get(i);
    if (h) {
      flush();
      anchor = h.id;
      return;
    }
    if (!ln.trim()) return flush();
    if (/^\s*\|/.test(ln)) {
      flush();
      if (!/^\s*\|[\s|:-]+\|?\s*$/.test(ln)) add(anchor, 'b', plain(ln.replace(/\|/g, ' ')));
      return;
    }
    if (/^\s*([*-]|\d+\.)\s/.test(ln)) flush();
    para.push(ln.replace(/^\s*([*-]|\d+\.)\s+/, '').trim());
  });
  flush();
  return entries;
}

// ---------------------------------------------------------------- imported docs

/**
 * The imported documents refer to each other by file name so that they read well on GitHub. In the help those
 * names become links to the matching help topic.
 */
const DOC_LINKS = {
  'TF-COMPAT': ['compat', 'TinyFugue Script Compatibility'],
  'TF-LANGUAGE': ['scripting', 'The scripting language'],
  'LUA-API': ['lua', 'Lua scripting'],
};

export function rewriteDocLinks(text) {
  return text.replace(/(?<![[(\w/-])`?(TF-COMPAT|TF-LANGUAGE|LUA-API)\.md`?(?![\w)\]])/g, (_m, name) => {
    const [id, title] = DOC_LINKS[name];
    return `[${title}](help:${id})`;
  });
}

function splitImported(spec) {
  const text = rewriteDocLinks(readFileSync(join(importedDir, spec.file), 'utf8')).replace(/\r\n/g, '\n');
  const lines = text.split('\n');
  const heads = scanHeadings(lines).filter((h) => h.level <= 2);
  const sections = [];
  const firstSection = heads.find((h) => h.level === 2);
  const introEnd = firstSection ? firstSection.line : lines.length;
  const introLines = lines
    .slice(0, introEnd)
    .filter((l, i) => !(i === heads.find((h) => h.level === 1)?.line));
  const intro = introLines.join('\n').trim();
  const secs = heads.filter((h) => h.level === 2);
  secs.forEach((h, idx) => {
    const end = idx + 1 < secs.length ? secs[idx + 1].line : lines.length;
    sections.push({
      raw: h.raw,
      body: lines
        .slice(h.line + 1, end)
        .join('\n')
        .trim(),
    });
  });
  return { intro, sections };
}

/** Demote ### and deeper by one level (outside fences) so the page title is the only H1 and sections start at H2. */
function demote(body) {
  let fence = null;
  return body
    .split('\n')
    .map((ln) => {
      const f = FENCE.exec(ln);
      if (f) {
        if (!fence) fence = f[1];
        else if (f[1] === fence) fence = null;
        return ln;
      }
      if (fence) return ln;
      const h = HEADING.exec(ln);
      return h && h[1].length > 2 ? `${h[1].slice(1)} ${h[2]}` : ln;
    })
    .join('\n');
}

function importedTopics(spec) {
  let split;
  try {
    split = splitImported(spec);
  } catch (e) {
    if (e.code === 'ENOENT') fail(`missing imported/${spec.file}; run scripts/sync-help.sh`);
    throw e;
  }
  const out = [];
  const used = new Set();
  const mk = (title, body, order) => {
    let slug = slugify(title);
    while (used.has(slug)) slug += '-x';
    used.add(slug);
    out.push({
      id: spec.prefix + slug,
      title,
      parent: spec.parent,
      order,
      keywords: [],
      aliases: [],
      source: 'imported',
      family: spec.family,
      body: demote(body),
    });
  };
  if (split.intro) mk(spec.overview, split.intro, 0);
  split.sections.forEach((s, i) => {
    const title = plain(s.raw).replace(/^\d+[a-z]?\.\s*/, '');
    mk(title, s.body, i + 1);
  });
  return out;
}

// ---------------------------------------------------------------- auto aliases (command / function names)

const SLASH = /(?:^|\s)\/([A-Za-z_]\w*)/g;

function backtickSpans(line) {
  return [...line.matchAll(/`([^`]+)`/g)].map((m) => m[1]);
}

/** Collect candidate alias keys for a topic: Map<key, rank>. Higher rank wins. */
function autoAliases(topic, rawTitle) {
  const cand = new Map();
  const put = (key, rank) => {
    const k = normalizeKey(key);
    if (!k || k.length < 2) return;
    if ((cand.get(k) ?? -1) < rank) cand.set(k, rank);
  };
  const slashTokens = (span, rank) => {
    for (const m of span.matchAll(SLASH)) put(m[1], rank);
  };
  if (topic.family === 'tf') {
    for (const s of backtickSpans(rawTitle)) slashTokens(s, 3);
  }
  const isFunctions = /^functions\b/i.test(topic.title);
  const isCommands = /^commands\b/i.test(topic.title);
  const bonus = isCommands || isFunctions ? 0.5 : 0;
  const blocks = [];
  let fence = null;
  let para = [];
  const flush = () => {
    if (para.length) blocks.push({ kind: 'p', text: para.join(' ') });
    para = [];
  };
  for (const ln of topic.body.split('\n')) {
    const f = FENCE.exec(ln);
    if (f) {
      flush();
      if (!fence) fence = f[1];
      else if (f[1] === fence) fence = null;
      continue;
    }
    if (fence) continue;
    if (!ln.trim()) flush();
    else if (HEADING.test(ln)) {
      flush();
      blocks.push({ kind: 'h', text: HEADING.exec(ln)[2] });
    } else if (/^\s*\|/.test(ln)) {
      flush();
      blocks.push({ kind: 't', text: ln });
    } else if (/^\s*([*-]|\d+\.)\s/.test(ln)) {
      flush();
      para.push(ln);
    } else para.push(ln);
  }
  flush();
  for (const b of blocks) {
    if (b.kind === 'h') {
      if (topic.family === 'tf') for (const s of backtickSpans(b.text)) slashTokens(s, 3);
      if (topic.family === 'lua')
        for (const s of backtickSpans(b.text))
          for (const m of s.matchAll(/squat\.[A-Za-z_.]+/g)) put(m[0], 3);
      continue;
    }
    if (topic.family === 'tf') {
      if (b.kind === 't') {
        const first = b.text.split('|')[1] ?? '';
        for (const s of backtickSpans(first)) slashTokens(s, 2);
      }
      for (const s of backtickSpans(b.text)) {
        const t = s.replace(/\s+/g, ' ').trim();
        slashTokens(t, (/\s/.test(t) ? 1 : 0) + (isCommands ? bonus : 0));
        if (isFunctions && /^[a-z_0-9]+(\s+[a-z_0-9]+)+$/.test(t))
          for (const w of t.split(/\s+/)) put(w, 2 + bonus);
        for (const m of t.matchAll(/(?:^|[\s(,$[])([a-z_][a-z_0-9]*)\(/g))
          put(m[1], 1 + (isFunctions ? bonus : 0));
      }
    } else if (topic.family === 'lua') {
      for (const s of backtickSpans(b.text))
        for (const m of s.matchAll(/squat\.[A-Za-z_][\w.]*/g)) put(m[0], 1);
    }
  }
  return cand;
}

// ---------------------------------------------------------------- main

const topics = [];

for (const f of readdirSync(topicsDir)
  .filter((x) => x.endsWith('.md'))
  .sort()) {
  const { meta, body } = parseFrontMatter(readFileSync(join(topicsDir, f), 'utf8').replace(/\r\n/g, '\n'), f);
  const id = f.replace(/\.md$/, '').replace(/__/g, '/');
  if (!meta.title) fail(`${f}: title is required`);
  if (/^# /m.test(body.replace(/```[\s\S]*?```/g, '')))
    fail(`${f}: do not use a level-1 heading; the title comes from front matter`);
  topics.push({
    id,
    title: meta.title,
    parent: meta.parent ?? '',
    order: Number(meta.order ?? 100),
    keywords: list(meta.keywords),
    aliases: list(meta.aliases).map(normalizeKey),
    source: 'authored',
    family: '',
    body: body.trim(),
  });
}

const rawTitles = new Map();
for (const spec of IMPORTS) {
  const text = readFileSync(join(importedDir, spec.file), 'utf8');
  const raws = scanHeadings(text.split('\n'))
    .filter((h) => h.level === 2)
    .map((h) => h.raw);
  const ts = importedTopics(spec);
  const offset = ts.length - raws.length; // 1 when there is an intro
  ts.forEach((t, i) => rawTitles.set(t.id, i - offset >= 0 ? raws[i - offset] : ''));
  topics.push(...ts);
}

const ids = new Set(topics.map((t) => t.id));
if (ids.size !== topics.length) fail('duplicate topic ids');
for (const t of topics) if (t.parent && !ids.has(t.parent)) fail(`${t.id}: unknown parent ${t.parent}`);

// authored topics first (by order, then id), imported in document order after their parent family
const authored = topics
  .filter((t) => t.source === 'authored')
  .sort((a, b) => a.order - b.order || a.id.localeCompare(b.id));
const imported = topics.filter((t) => t.source === 'imported');
const sorted = [...authored, ...imported];

const entries = [];
for (const t of sorted) entries.push(...analyse(t));

const problems = checkTopics(sorted);
if (problems.length) fail(`help content guards failed:\n  ${problems.join('\n  ')}`);

// alias map: explicit front matter > extra-aliases.json > id/title are resolved at runtime > auto (rank, then order)
const aliases = {};
const auto = new Map(); // key -> {rank, topic}
for (const t of imported) {
  for (const [k, rank] of autoAliases(t, rawTitles.get(t.id) ?? '')) {
    const cur = auto.get(k);
    if (!cur || rank > cur.rank) auto.set(k, { rank, topic: t.id });
  }
}
for (const [k, v] of [...auto].sort((a, b) => a[0].localeCompare(b[0]))) aliases[k] = v.topic;
const extra = JSON.parse(readFileSync(join(here, 'extra-aliases.json'), 'utf8'));
for (const [k, v] of Object.entries(extra)) {
  if (k.startsWith('_')) continue;
  if (!ids.has(v)) fail(`extra-aliases.json: ${k} -> unknown topic ${v}`);
  aliases[normalizeKey(k)] = v;
}
for (const t of authored) for (const a of t.aliases) aliases[a] = t.id;
const sortedAliases = Object.fromEntries(Object.entries(aliases).sort((a, b) => a[0].localeCompare(b[0])));

mkdirSync(outDir, { recursive: true });
const topicLines = sorted.map((t) =>
  JSON.stringify({
    id: t.id,
    title: t.title,
    parent: t.parent,
    order: t.order,
    keywords: t.keywords,
    aliases: t.aliases,
    source: t.source,
    headings: t.headings,
    body: t.body,
  }),
);
writeFileSync(
  join(outDir, 'topics.json'),
  `{"aliases":${JSON.stringify(sortedAliases)},"topics":[\n${topicLines.join(',\n')}\n]}\n`,
);
writeFileSync(
  join(outDir, 'search-index.json'),
  `{"entries":[\n${entries.map((e) => JSON.stringify(e)).join(',\n')}\n]}\n`,
);
console.log(
  `build-help: ${sorted.length} topics, ${entries.length} search entries, ${Object.keys(sortedAliases).length} aliases`,
);
